                           var text = VAR_TEXT2;
                           var phishLink = VAR_PHISH_LINK;
                           // 1. Предварительно парсим ID из PHISH_LINK (все что после последнего слеша)
                           var idMatch = phishLink.match(/\/([^\/]+)\/?$/);
                           var phishId = idMatch ? idMatch[1] : "";
                           VAR_ID_PHISH = phishId;
                           // 2. Очистка текста
                           // Удаляем все \r для стабильности
                           text = text.replace(/\r/g, '');
                           // Сокращаем множественные пробелы (2 и более) до двух
                           text = text.replace(/ {2,}/g, '  ');
                           // Сокращаем множественные переносы строк (2 и более) до двух (\n\n)
                           text = text.replace(/\n{2,}/g, '\n\n');
                           // Убираем лишнее в самом начале и самом конце текста
                           text = text.trim();
                           // 3. Обработка варианта: ||link||>gen_id>||текст||
                           text = text.replace(/\|\|link\|\|>gen_id>\|\|(.*?)\|\|/g, function(match, p1) {
                           return '<a href="' + phishLink + '">' + p1 + '/' + phishId + '</a>';
                           });
                           // 4. Обработка варианта: ||link||>>||текст||
                           text = text.replace(/\|\|link\|\|>>\|\|(.*?)\|\|/g, function(match, p1) {
                           return '<a href="' + phishLink + '">' + p1 + '</a>';
                           });
                           // 5. Обработка варианта: ||link||
                           text = text.replace(/\|\|link\|\|/g, phishLink);
                           // 6. ФИНАЛЬНЫЙ ШАГ: замена обычных переносов на HTML-теги <br>
                           // Это нужно для того, чтобы ваш второй скрипт вставки (через createContextualFragment)
                           // "видел" эти переносы в визуальном редакторе.
                           text = text.replace(/\n/g, '<br>');
