[{"data": "const XLSX = require('xlsx');
try {
 const filePath = [[PARSED_DATA]];
 const loginVal = String([[LOGIN]] || "").trim();
 const BATCH_SIZE = 100;
 const workbook = XLSX.readFile(filePath);
 const s0 = workbook.SheetNames[0];
 const s1 = workbook.SheetNames[1] || "Обработанные";
 let d0 = XLSX.utils.sheet_to_json(workbook.Sheets[s0], { header: 1, defval: "" });
 let d1 = workbook.Sheets[s1]
 ? XLSX.utils.sheet_to_json(workbook.Sheets[s1], { header: 1, defval: "" })
 : [];
 const hdr = d0[0] || [];
 const rows = d0.slice(1);
 const batch = rows.slice(0, BATCH_SIZE);
 let lines = [];
 for (let row of batch) {
 const email = String(row[0] || "").trim();
 const subj = String(row[1] || "").trim();
 if (email && subj) lines.push(email + "\t" + subj);
 let nr = [...row]; nr[3] = loginVal; nr[4] = 1; d1.push(nr);
 }
 const remaining = [hdr].concat(rows.slice(BATCH_SIZE));
 workbook.Sheets[s0] = XLSX.utils.aoa_to_sheet(remaining);
 if (!workbook.SheetNames.includes(s1)) {
 XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet(d1), s1);
 } else {
 workbook.Sheets[s1] = XLSX.utils.aoa_to_sheet(d1);
 }
 XLSX.writeFile(workbook, filePath);
 [[CLIPBOARD_DATA]] = lines.join("\n");
 [[BATCH_COUNT]] = lines.length;
 console.log("Batch: " + lines.length + " emails loaded for " + loginVal);
} catch(e) {
 console.log("batch_read error: " + e.message);
 [[BATCH_COUNT]] = 0; [[CLIPBOARD_DATA]] = "";
}", "data_name": "batch_read_mats", "data_type": 0, "language_name": "Node", "language_version": "22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 // 1. Читаем файл
 const workbook = XLSX.readFile([[CONFIG_BAS]]);
 const sheetName = workbook.SheetNames[0];
 const worksheet = workbook.Sheets[sheetName];

 // 2. Обязательно добавляем { header: 1 }, чтобы работать с индексами 0, 1, 2...
 const data = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: "" });

 // 3. Получаем индекс
 // Если первая строка в таблице — это заголовки, прибавьте +1: parseInt([[THREAD_INDEX]]) + 1
 const index = parseInt([[THREAD_INDEX]]);
 const row = data[index];

 if (row) {
 // Присваиваем значения переменным BAS напрямую
 // Убедитесь, что эти переменные созданы в интерфейсе BAS
 [[ID]] = row[0];
 [[LOGIN]] = row[1];
 [[PASS]] = row[2];
 [[RECOVERY_MAIL]] = row[3];
 [[TWO_FA_KEY]] = row[4];
 [[PROXY]] = row[5];
 [[BANED]] = row[6];
 [[DAILY_LIMIT]] = row[7];
 [[CURRENT_LIMIT]] = row[8];
 [[STATUS_LIMIT]] = row[9];

 console.log("Данные воркера: " + row[1] + " для потока " + index + " успешно загружены.");
 } else {
 console.log("Ошибка: Строка с индексом " + index + " не найдена!");
 }
} catch (e) {
 console.log("Произошла ошибка при чтении Excel: " + e.message);
}","data_name":"rfnliwhipgi","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 // 1. Читаем файл
 const workbook = XLSX.readFile([[CONFIG_BAS]]);
 const sheetName = workbook.SheetNames[0];
 const worksheet = workbook.Sheets[sheetName];

 // 2. Преобразуем в массив массивов (header: 1), чтобы работать с индексами
 const data = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

 // 3. Определяем нужную строку (индекс из BAS)
 const index = parseInt([[THREAD_INDEX]]);

 if (data[index]) {
 // 4. Изменяем данные в 10-й колонке (индекс 10 — это 11-й столбец, "baned")
 // Если индекс в Excel начинается с 0, то 10 — это именно ваш "baned"
 data[index][11] = true;

 // 5. Создаем новый лист из обновленного массива данных
 const newWorksheet = XLSX.utils.aoa_to_sheet(data);

 // 6. Заменяем старый лист в книге на новый
 workbook.Sheets[sheetName] = newWorksheet;

 // 7. Записываем обновленный файл обратно
 XLSX.writeFile(workbook, [[CONFIG_BAS]]);

 console.log("Строка " + index + ", колонка 11 обновлена на true.");
 } else {
 console.log("Ошибка: Строка не найдена, нечего обновлять.");
 }

} catch (e) {
 console.log("Ошибка при записи в Excel: " + e.message);
}","data_name":"hvwp8c8syz","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[CONFIG_BAS]];
 const workbook = XLSX.readFile(filePath);
 const threadIndex = parseInt([[THREAD_INDEX]]);

 // Получаем названия листов
 const sheet0Name = workbook.SheetNames[0];
 const sheet1Name = workbook.SheetNames[1];
 const sheet2Name = workbook.SheetNames[2];

 // Преобразуем листы в массивы (AOA - Array of Arrays)
 let sheet0Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet0Name], { header: 1, defval: "" });
 let sheet1Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet1Name], { header: 1, defval: "" });
 let sheet2Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet2Name], { header: 1, defval: "" });

 // --- ШАГ 1: Перенос из Листа 0 на Лист 1 в конец ---
 const rowToMove = sheet0Data[threadIndex];
 if (rowToMove) {
 sheet1Data.push(rowToMove);
 console.log("Строка из Листа 0 перенесена в конец Листа 1");
 }

 // --- ШАГ 2: Взять строку из Листа 2 (индекс 1) с удалением (вырезанием) ---
 let newRowData = null;
 if (sheet2Data.length > 1) {
 // splice(1, 1) удаляет 1 элемент на позиции 1 и возвращает его
 // Это автоматически "сдвигает" все остальные строки вверх, убирая пробел
 newRowData = sheet2Data.splice(1, 1)[0];
 console.log("Строка из Листа 2 извлечена, данные сдвинуты");
 } else {
 console.log("На Листе 2 нет данных для переноса (кроме заголовков)");
 }

 // --- ШАГ 3: Замена строки на Листе 0 ---
 if (newRowData) {
 // Заменяем данные на Листе 0 в позиции потока
