}","data_name":"yyq2gebhsc","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 // --- 1. РАБОТА С CONFIG_BAS (Увеличение счетчика) ---
 const configPath = [[CONFIG_BAS]];
 const configIdx = parseInt([[THREAD_INDEX]]);
 
 const wbConfig = XLSX.readFile(configPath);
 const sheetConfigName = wbConfig.SheetNames[0];
 let configData = XLSX.utils.sheet_to_json(wbConfig.Sheets[sheetConfigName], { header: 1, defval: "" });

 if (configData[configIdx]) {
 let currentValue = Number(configData[configIdx][8]) || 0;
 configData[configIdx][8] = currentValue + 1;

 wbConfig.Sheets[sheetConfigName] = XLSX.utils.aoa_to_sheet(configData);
 XLSX.writeFile(wbConfig, configPath);
 console.log("CONFIG_BAS: отписок на аккаунте " + configData[configIdx][1] + " сделано " + configData[configIdx][8]);
 }

 // --- 2. РАБОТА С PARSED_DATA (Поиск по фильтрам и обновление) ---
 const parsedPath = [[PARSED_DATA]];
 const targetEmail = String([[EMAIL]] || "").trim();
 const targetName = String([[NAME_LISTING]] || "").trim();

 const wbParsed = XLSX.readFile(parsedPath);
 const sheetParsedName = wbParsed.SheetNames[1]; 
 let parsedData = XLSX.utils.sheet_to_json(wbParsed.Sheets[sheetParsedName], { header: 1, defval: "" });

 let isUpdated = false;

 // Ищем строку, начиная с начала (пропускаем заголовок, если он есть)
 for (let i = 0; i < parsedData.length; i++) {
 const row = parsedData[i];
 
 // Проверяем совпадение: Индекс 0 (Email) и Индекс 1 (Name)
 if (String(row[0]).trim() === targetEmail && String(row[1]).trim() === targetName) {
 
 // Меняем статус в колонке с индексом 4 на 1
 parsedData[i][4] = 1; 
 isUpdated = true;
 
 console.log("PARSED_DATA: Найдена строка " + (i + 1) + ". Статус объявления '" + targetName + "' изменен на 1");
 break; // Выходим из цикла после первого найденного совпадения
 }
 }

 if (isUpdated) {
 wbParsed.Sheets[sheetParsedName] = XLSX.utils.aoa_to_sheet(parsedData);
 XLSX.writeFile(wbParsed, parsedPath);
 } else {
 console.log("PARSED_DATA: Строка с Email '" + targetEmail + "' и названием '" + targetName + "' не найдена.");
 }

} catch (e) {
 console.log("Ошибка при обновлении данных: " + e.message);
}","data_name":"qiuu4c5n0rf","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

