try {
 const filePath = [[CONFIG_BAS]];
 const workbook = XLSX.readFile(filePath);
 const threadIndex = parseInt([[THREAD_INDEX]]);

 // Получаем названия листов
 const sheet0Name = workbook.SheetNames[0];
 const sheet1Name = workbook.SheetNames[1];
 const sheet2Name = workbook.SheetNames[2];

 // Преобразуем листы в массивы (AOA - Array of Arrays)
 let sheet0Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet0Name], { header: 1, defval: "" });
 let sheet1Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet1Name], { header: 1, defval: "" });
 let sheet2Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet2Name], { header: 1, defval: "" });

 // --- ШАГ 1: Перенос из Листа 0 на Лист 1 в конец ---
 const rowToMove = sheet0Data[threadIndex];
 if (rowToMove) {
 sheet1Data.push(rowToMove);
 console.log("Строка из Листа 0 перенесена в конец Листа 1");
 }

 // --- ШАГ 2: Взять строку из Листа 2 (индекс 1) с удалением (вырезанием) ---
 let newRowData = null;
 if (sheet2Data.length > 1) {
 // splice(1, 1) удаляет 1 элемент на позиции 1 и возвращает его
 // Это автоматически "сдвигает" все остальные строки вверх, убирая пробел
 newRowData = sheet2Data.splice(1, 1)[0];
 console.log("Строка из Листа 2 извлечена, данные сдвинуты");
 } else {
 console.log("На Листе 2 нет данных для переноса (кроме заголовков)");
 }

 // --- ШАГ 3: Замена строки на Листе 0 ---
 if (newRowData) {
 // Заменяем данные на Листе 0 в позиции потока
 sheet0Data[threadIndex] = newRowData;
 console.log("Данные на Листе 0 обновлены данными из Листа 2");
 }

 // --- СОХРАНЕНИЕ ---
 // Превращаем массивы обратно в листы Excel
 workbook.Sheets[sheet0Name] = XLSX.utils.aoa_to_sheet(sheet0Data);
 workbook.Sheets[sheet1Name] = XLSX.utils.aoa_to_sheet(sheet1Data);
 workbook.Sheets[sheet2Name] = XLSX.utils.aoa_to_sheet(sheet2Data);

 // Записываем файл
 XLSX.writeFile(workbook, filePath);
 console.log("Все изменения успешно сохранены в файл");

} catch (e) {
 console.log("Критическая ошибка: " + e.message);
}","data_name":"r6pmy24usre","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');
const fs = require('fs');

let success = false;
let attempts = 0;

while (!success) {
 try {
 const filePath = [[PARSED_DATA]];
 
 if (!fs.existsSync(filePath)) {
 throw new Error("Файл не найден");
 }

 // 1. Читаем книгу
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[0]; 
 const worksheet = workbook.Sheets[sheetName];

 // 2. Преобразуем в массив массивов
 // header: 1 возвращает данные как массив строк
 const data = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: "" });

 // 3. Подсчет без фильтрации
 // Если строк меньше или равно 1 — значит данных нет (только заголовок или пусто)
 let count = 0;
 if (data.length > 1) {
 count = data.length - 1; // Вычитаем строку заголовка
 }

 // Сохраняем результат в переменную BAS
 [[COUNT_LISTING]] = count;

 console.log("Общее количество объявлений в таблице (без учета заголовка): " + count);
 
 success = true; 

 } catch (e) {
 attempts++;
 
 // Задержка 100 мс (актуально, если файл занят другим процессом)
 var start = new Date().getTime();
 while (new Date().getTime() < start + 100); 
 
 if (attempts > 500) {
 console.log("Критическая ошибка: не удалось обработать файл после 500 попыток. " + e.message);
 [[COUNT_LISTING]] = 0;
 break;
 }
 }
}","data_name":"rdi8gnx431p","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[PARSED_DATA]];
 // Тема из BAS для поиска (базовая)
 const searchSubject = [[SUBJECT]].toString().trim().toLowerCase();
 const searchLogin = [[LOGIN]].toString().trim().toLowerCase();
 
 // 1. Читаем книгу
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[1]; // Лист с индексом 1
 
 if (!sheetName) {
 throw new Error("Лист с индексом 1 не найден в файле");
 }

 // 2. Преобразуем лист в массив массивов
 let data = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: "" });

 let updatedCount = 0;

 // 3. Поиск по всем строкам
 // Начинаем с 1, если есть заголовки. Если данных много, цикл проверит всё.
 for (let i = 1; i < data.length; i++) {
 const row = data[i];

 // Приводим данные из Excel к нижнему регистру для гибкого поиска
 const rowSubject = row[1] ? row[1].toString().trim().toLowerCase() : "";
 const rowLogin = row[3] ? row[3].toString().trim().toLowerCase() : "";

 // Условие: частичное совпадение темы И строгое совпадение логина
 const subjectMatch = rowSubject.includes(searchSubject) || searchSubject.includes(rowSubject);
 const loginMatch = (rowLogin === searchLogin);

 if (subjectMatch && loginMatch) {
 // 4. Меняем статус на 2 во всех найденных строках
 data[i][4] = 2; 
 updatedCount++;
 }
 }

 // 5. Если хотя бы одна запись была изменена, сохраняем файл
 if (updatedCount > 0) {
 workbook.Sheets[sheetName] = XLSX.utils.aoa_to_sheet(data);
 XLSX.writeFile(workbook, filePath);
 
 console.log("Обновление завершено. Изменено строк: " + updatedCount + " для темы: " + [[SUBJECT]]);
 [[IS_UPDATED]] = true;
 } else {
 console.log("Ни одной записи для обновления не найдено.");
 [[IS_UPDATED]] = false;
 }

} catch (e) {
 console.log("Ошибка при массовом обновлении PARSED_DATA: " + e.message);
 [[IS_UPDATED]] = false;
}","data_name":"vopi9om1ef9","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[PARSED_DATA]];
 // Тема письма, которую мы получили (приводим к нижнему регистру для поиска)
 const searchSubject = [[SUBJECT]].toString().trim().toLowerCase();
 const searchLogin = [[LOGIN]].toString().trim().toLowerCase();
 
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[1]; // Лист с индексом 1
 
 if (!sheetName) throw new Error("Лист с индексом 1 не найден");

 const data = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: "" });
 let found = false;

 // Перебор строк (пропускаем заголовки)
 for (let i = 1; i < data.length; i++) {
 const row = data[i];

 // Индекс 1 — Название товара (Item Name)
 // Индекс 3 — Логин (Login)
 // Индекс 4 — Статус
 const rowItemName = row[1] ? row[1].toString().trim().toLowerCase() : "";
 const rowLogin = row[3] ? row[3].toString().trim().toLowerCase() : "";
 const rowStatus = row[4];

 // Сравнение логина
 const loginMatch = (rowLogin === searchLogin);

 // Сравнение товара и темы письма (содержит ли одно другое)
 // Мы проверяем, есть ли название товара внутри темы письма
 const itemMatch = rowItemName !== "" && (searchSubject.includes(rowItemName) || rowItemName.includes(searchSubject));

 // Проверка статуса (0 или 1)
 const statusValue = Number(rowStatus);
 const statusMatch = (statusValue === 0 || statusValue === 1);

 if (loginMatch && itemMatch && statusMatch) {
 // Если всё совпало, берем ссылку из колонки с индексом 2
 [[LINK]] = row[2];
 found = true;
 break; 
 }
 }

 if (found) {
 [[IS_FONDED]] = true;
 console.log("Запись успешно найдена по товару и логину. Товар: " + [[SUBJECT]]);
 } else {
 [[IS_FONDED]] = false;
 console.log("Запись не найдена. Логин: " + searchLogin + " | Тема: " + searchSubject);
 }

} catch (e) {
 console.log("Ошибка при поиске в PARSED_DATA: " + e.message);
 [[IS_FONDED]] = false;
}","data_name":"svobr4zcxy","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[CONFIG_BAS]];
 const workbook = XLSX.readFile(filePath);
 const threadIndex = parseInt([[THREAD_INDEX]]);
 const targetMarketplace = [[MARKETPLACE]].toString().trim().toLowerCase();

 const sheet0Name = workbook.SheetNames[0];
 const sheet1Name = workbook.SheetNames[1];
 const sheet2Name = workbook.SheetNames[2];

 let sheet0Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet0Name], { header: 1, defval: "" });
 let sheet1Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet1Name], { header: 1, defval: "" });
 let sheet2Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet2Name], { header: 1, defval: "" });

 // --- ШАГ 1: Перенос старой строки из Листа 0 на Лист 1 ---
 const rowToMove = sheet0Data[threadIndex];
 if (rowToMove && rowToMove.length > 0) {
 sheet1Data.push(rowToMove);
 console.log("Старая строка из Листа 0 успешно архивирована в Лист 1");
 }

 // --- ШАГ 2: Поиск подходящей строки на Листе 2 по индексу 6 ---
 let newRowData = null;
 let foundIndex = -1;

 for (let i = 1; i < sheet2Data.length; i++) {
 // Проверяем колонку под индексом 6 (это колонка G в Excel)
 const currentRowMarketplace = sheet2Data[i][6] ? sheet2Data[i][6].toString().trim().toLowerCase() : "";
 
 if (currentRowMarketplace === targetMarketplace) {
 foundIndex = i;
 break;
 }
 }

 if (foundIndex !== -1) {
 // Извлекаем (вырезаем) найденную строку
 newRowData = sheet2Data.splice(foundIndex, 1)[0];
 console.log(`Найдена строка для "${targetMarketplace}" в колонке 6 (индекс строки в массиве: ${foundIndex})`);
 } else {
 // Если ничего не нашли, выводим предупреждение в лог BAS
 console.log(`ВНИМАНИЕ: На Листе 2 нет свободных строк для маркетплейса "${targetMarketplace}"`);
 }

 // --- ШАГ 3: Замена данных на Листе 0 ---
 if (newRowData) {
 sheet0Data[threadIndex] = newRowData;
 console.log("Поток №" + threadIndex + " получил новые данные");
 
 // Помечаем для BAS, что замена прошла успешно
 [[IS_REPLACED]] = true; 
 } else {
 [[IS_REPLACED]] = false;
 }

 // --- СОХРАНЕНИЕ ---
 workbook.Sheets[sheet0Name] = XLSX.utils.aoa_to_sheet(sheet0Data);
 workbook.Sheets[sheet1Name] = XLSX.utils.aoa_to_sheet(sheet1Data);
 workbook.Sheets[sheet2Name] = XLSX.utils.aoa_to_sheet(sheet2Data);

 XLSX.writeFile(workbook, filePath);
 console.log("Файл конфигурации обновлен");

} catch (e) {
 console.log("Ошибка в функции замены строк: " + e.message);
 [[IS_REPLACED]] = false;
}","data_name":"r0e5owt0cya","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[CONFIG_BAS]];
