 // По умолчанию 0 (ошибка)
 [[STATUS_CHANGE]] = 0;
 [[IS_SUCCESS]] = false;

 const workbook = XLSX.readFile(filePath);
 
 const sheet0Name = workbook.SheetNames[0]; // Лист с воркерами
 const sheet2Name = workbook.SheetNames[2]; // Лист с резервом
 const sheet3Name = workbook.SheetNames[3]; // Лист с архивом

 let sheet0Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet0Name], { header: 1, defval: "" });
 let sheet2Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet2Name], { header: 1, defval: "" });
 let sheet3Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet3Name], { header: 1, defval: "" });

 // Проверяем, существует ли строка воркера в Листе 0
 if (sheet0Data[threadIndex]) {
 
 // --- ШАГ 1: Архивируем старые данные из Листа 0 в Лист 3 ---
 const rowToArchive = [...sheet0Data[threadIndex]];
 const timestamp = new Date().toLocaleString();
 rowToArchive[18] = timestamp; // Записываем время архивации в колонку S (индекс 18)
 sheet3Data.push(rowToArchive);
 console.log(`Поток ${threadIndex}: Старые данные отправлены в архив.`);

 // --- ШАГ 2: Берем САМУЮ ПЕРВУЮ строку из Резерва (Лист 2) ---
 // Индекс 0 — это заголовки, поэтому первая строка данных — это индекс 1
 if (sheet2Data.length > 1) {
 // .splice(1, 1) удаляет одну строку по индексу 1 и возвращает её массивом
 const replacementRow = sheet2Data.splice(1, 1)[0];
 
 // Заменяем строку воркера на новую из резерва
 sheet0Data[threadIndex] = replacementRow;
 
 [[STATUS_CHANGE]] = 1; // Успешная замена
 console.log(`Поток ${threadIndex}: Взята новая строка из резерва (индекс 1).`);
 } else {
 // Если в резерве только заголовки (длина 1) или пусто
 console.log(`Поток ${threadIndex}: РЕЗЕРВ ПУСТ! Очищаю рабочую строку.`);
 sheet0Data[threadIndex] = []; // Очищаем строку, так как заменять нечем
 
 [[STATUS_CHANGE]] = 2; // Резерв закончился
 }

 // --- ШАГ 3: Сохранение всех листов обратно в файл ---
 workbook.Sheets[sheet0Name] = XLSX.utils.aoa_to_sheet(sheet0Data);
 workbook.Sheets[sheet2Name] = XLSX.utils.aoa_to_sheet(sheet2Data);
 workbook.Sheets[sheet3Name] = XLSX.utils.aoa_to_sheet(sheet3Data);

 XLSX.writeFile(workbook, filePath);
 [[IS_SUCCESS]] = true;

 } else {
 console.log("Ошибка: Индекс потока " + threadIndex + " не найден в Листе 0.");
 [[IS_SUCCESS]] = false;
 }

} catch (e) {
 console.error("Критическая ошибка при ротации аккаунтов: " + e.message);
 [[STATUS_CHANGE]] = 0;
 [[IS_SUCCESS]] = false;
}","data_name":"8pqgrt62fxr","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 // 1. Читаем файл
 const workbook = XLSX.readFile([[CONFIG_BAS]]);
 const sheetName = workbook.SheetNames[0];
 const worksheet = workbook.Sheets[sheetName];

 // 2. Преобразуем в массив массивов (header: 1), чтобы работать с индексами
 const data = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

 // 3. Определяем нужную строку (индекс из BAS)
 const index = parseInt([[THREAD_INDEX]]);

 if (data[index]) {
 // 4. Изменяем данные в 7-й колонке (индекс 6 — это 7-й столбец, "baned")
 // Если индекс в Excel начинается с 0, то 6 — это именно ваш "baned"
 data[index][6] = true;

 // 5. Создаем новый лист из обновленного массива данных
 const newWorksheet = XLSX.utils.aoa_to_sheet(data);

 // 6. Заменяем старый лист в книге на новый
 workbook.Sheets[sheetName] = newWorksheet;

 // 7. Записываем обновленный файл обратно
 XLSX.writeFile(workbook, [[CONFIG_BAS]]);

 console.log("Строка " + index + ", колонка baned обновлена на true.");
 } else {
 console.log("Ошибка: Строка не найдена, нечего обновлять.");
 }

} catch (e) {
 console.log("Ошибка при записи в Excel: " + e.message);
}","data_name":"e5cscsg419n","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[CONFIG_BAS]];
 const workbook = XLSX.readFile(filePath);
 const threadIndex = parseInt([[THREAD_INDEX]]);

 const sheet0Name = workbook.SheetNames[0];
 const sheet1Name = workbook.SheetNames[1];
 const sheet2Name = workbook.SheetNames[2];

 let sheet0Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet0Name], { header: 1, defval: "" });
 let sheet1Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet1Name], { header: 1, defval: "" });
 let sheet2Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet2Name], { header: 1, defval: "" });

 // --- ШАГ 1: Перенос старой строки из Листа 0 на Лист 1 ---
 const rowToMove = sheet0Data[threadIndex];
 if (rowToMove && rowToMove.length > 0) {
 sheet1Data.push(rowToMove);
 console.log("Старая строка из Листа 0 успешно архивирована в Лист 1");
 }

 // --- ШАГ 2: Взять самую первую строку (индекс 1) без фильтрации ---
 let newRowData = null;

 // Проверяем, что в таблице больше 1 строки (индекс 0 - заголовки, индекс 1 - данные)
 if (sheet2Data.length > 1) {
 // splice(1, 1) вырезает одну строку по индексу 1. 
 // Все остальные строки автоматически сдвигаются вверх.
 newRowData = sheet2Data.splice(1, 1)[0];
 console.log("Взята первая доступная строка из Листа 2 (индекс 1)");
 } else {
 console.log("ВНИМАНИЕ: На Листе 2 больше нет свободных строк с данными");
 }

 // --- ШАГ 3: Замена данных на Листе 0 ---
 if (newRowData) {
 sheet0Data[threadIndex] = newRowData;
 console.log("Поток №" + threadIndex + " получил новые данные");
 
 // Помечаем для BAS, что замена прошла успешно
 [[IS_REPLACED]] = true; 
 } else {
 [[IS_REPLACED]] = false;
 }

 // --- СОХРАНЕНИЕ ---
 workbook.Sheets[sheet0Name] = XLSX.utils.aoa_to_sheet(sheet0Data);
 workbook.Sheets[sheet1Name] = XLSX.utils.aoa_to_sheet(sheet1Data);
 workbook.Sheets[sheet2Name] = XLSX.utils.aoa_to_sheet(sheet2Data);

 XLSX.writeFile(workbook, filePath);
 console.log("Файл конфигурации обновлен (строка заменена по порядку)");

} catch (e) {
 console.log("Ошибка в функции замены строк: " + e.message);
 [[IS_REPLACED]] = false;
}","data_name":"mim3aj30ngi","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');
const fs = require('fs');

let success = false;
let attempts = 0;

while (!success) {
 try {
 const filePath = [[PARSED_DATA]];
 
 if (!fs.existsSync(filePath)) {
 throw new Error("Файл не найден");
 }

 // 1. Читаем книгу
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[0]; 
 const worksheet = workbook.Sheets[sheetName];

 // 2. Преобразуем в массив массивов
 // header: 1 возвращает данные как массив строк
 const data = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: "" });

 // 3. Подсчет без фильтрации
 // Если строк меньше или равно 1 — значит данных нет (только заголовок или пусто)
 let count = 0;
 if (data.length > 1) {
 count = data.length - 1; // Вычитаем строку заголовка
 }

 // Сохраняем результат в переменную BAS
 [[COUNT_LISTING]] = count;

 console.log("Общее количество объявлений в таблице (без учета заголовка): " + count);
 
 success = true; 

 } catch (e) {
 attempts++;
 
 // Задержка 100 мс (актуально, если файл занят другим процессом)
 var start = new Date().getTime();
 while (new Date().getTime() < start + 100); 
 
 if (attempts > 500) {
 console.log("Критическая ошибка: не удалось обработать файл после 500 попыток. " + e.message);
 [[COUNT_LISTING]] = 0;
 break;
 }
 }
}","data_name":"rq53v20zuf","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const cheerio = require('cheerio');

// Входящая переменная из BAS (содержимое страницы)
// Предположим, ты сохранил код страницы в переменную [[SAVED_HTML]]
let html = [[SAVED_PAGE_HTML]]; 
const $ = cheerio.load(html);

// 1. Title (из мета-тегов или title)
let title = $('title').text().split('|')[0].trim();

// 2. Достаем JSON с данными (там есть цена, картинки и параметры)
let adData = {};
const jsonText = $('#advertising-initial-state').html();

if (jsonText) {
 try {
 const fullJson = JSON.parse(jsonText);
 const targeting = fullJson.config.adServer.gam.targeting;
 
 // Преобразуем массив таргетинга в удобный объект
 targeting.forEach(item => {
 adData[item.key] = item.value[0];
 });
 } catch (e) {
 console.error("Ошибка парсинга JSON:", e);
 }
}

// 3. Собираем финальные данные
let result = {
 title: title,
 price: adData['price'] || "Не найдено",
 address: adData['zipcode'] || "Не найдено", // В коде есть только индекс
 image_url: $('meta[property="og:image"]').attr('content') || adData['images'],
 seller_name: adData['owner_type'] === 'private' ? 'Private' : 'Private' 
};

// 4. Передаем данные обратно в переменные BAS
[[TITLE]] = result.title;
[[PRICE]] = result.price;
[[ADDRESS]] = result.address;
[[IMAGE_URL]] = result.image_url;
[[SELLER_NAME]] = result.seller_name;","data_name":"t5zdsgkyg1","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

try {
 // 1. Извлекаем значения из BAS в переменные Node.js
 const title = [[TITLE]];
 const price = [[PRICE]];
 const name = [[MY_NAME]];
 const address = [[MY_ADRESS]];
 const img = [[IMAGE_URL]];
 const domain = [[DOMAIN]].replace('https://', '').split('/')[0];
 const apiKey = [[APIKEY]];

 // 2. Формируем JSON
 const payload = JSON.stringify({
 "country_code": "SE",
 "service_code": "blocket",
 "title": title,
 "price": Number(price),
 "profile": {
 "full_name": name,
 "address": address
 },
 "images": {
 "0": {
 "url": img,
 "type": "image/jpeg"
 }
 }
 });

 // 3. Сохраняем во временный файл (UTF-8 с BOM для шведских букв)
 const jsonPath = path.join(process.env.TEMP, 'data_post.json');
 fs.writeFileSync(jsonPath, '\ufeff' + payload, 'utf8');

 // 4. Формируем команду PowerShell
 // Мы вставляем переменные ${domain} и ${apiKey} прямо в строку JS
 const psScript = `
 [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12;
 $body = Get-Content -Path "${jsonPath.replace(/\\/g, '\\\\')}" -Raw -Encoding UTF8;
 $headers = @{
 "X-API-KEY" = "${apiKey}"
 "Content-Type" = "application/json; charset=utf-8"
 };
 $res = Invoke-WebRequest -Uri "https://${domain}/api/v1/ad/create" -Method Post -Headers $headers -Body $body -UseBasicParsing;
 Write-Output "CODE:$($res.StatusCode)";
 Write-Output "BODY:$($res.Content)";
 `.trim();

 // Кодируем команду в Base64 (UTF-16LE) для PowerShell
 const b64Command = Buffer.from(psScript, 'utf16le').toString('base64');
 
 // 5. Выполняем
 const output = execSync(`powershell -NoProfile -EncodedCommand ${b64Command}`, { encoding: 'utf8' });

 // 6. Парсим ответ
 let status = 0;
 let body = "";
 output.split('\n').forEach(line => {
 if (line.includes('CODE:')) status = line.split('CODE:')[1].trim();
 if (line.includes('BODY:')) body = line.split('BODY:')[1].trim();
 });

 [[RESPONSE_STATUS]] = parseInt(status);
 [[RESPONSE_BODY]] = body;

 console.log("Status: " + status);
 console.log("Body: " + body);

 // Чистим за собой
 if (fs.existsSync(jsonPath)) fs.unlinkSync(jsonPath);

} catch (e) {
 // Вытаскиваем текст ошибки из PowerShell если он есть
 const errorLog = e.stdout ? e.stdout.toString() : e.message;
 console.error("Ошибка: " + errorLog);
 [[RESPONSE_STATUS]] = 500;
 [[RESPONSE_BODY]] = errorLog;
}","data_name":"ube7rlq7g28","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const cheerio = require('cheerio');

let html = [[SAVED_PAGE_HTML]]; 
const $ = cheerio.load(html);

let result = {
 title: "Не найдено",
 price: "Не найдено",
 currency: "Не найдено",
 address: "Не найдено",
 image_url: "",
 seller_name: "Private"
};

// 1. Title (берем чистый заголовок до разделителя)
let titleRaw = $('meta[property="og:title"]').attr('content') || $('h1').text().trim();
if (titleRaw) result.title = titleRaw.split('|')[0].trim();

// 2. Парсим JSON-LD (самый надежный источник для цены и валюты)
const jsonLdScripts = $('script[type="application/ld+json"]');

jsonLdScripts.each((i, el) => {
 try {
 const content = $(el).html();
 const ldData = JSON.parse(content);
 
 // Нам нужен объект с типом Product
 if (ldData['@type'] === 'Product' || ldData.offers) {
 const offers = ldData.offers;
 if (offers) {
 result.price = offers.price || "Не найдено";
 result.currency = offers.priceCurrency || "Не найдено";
 }
 if (ldData.image) result.image_url = ldData.image;
 }
 } catch (e) {
 console.error("Ошибка парсинга одного из блоков JSON-LD");
 }
});

// 3. Достаем адрес и продавца (тут все же заглянем в __NEXT_DATA__, так как в LD этого мало)
try {
 const nextDataText = $('#__NEXT_DATA__').html();
 if (nextDataText) {
 const nextData = JSON.parse(nextDataText);
 // В Tradera данные продавца обычно лежат глубоко в pageProps
 const seller = nextData.props.pageProps.initialState?.viewItem?.itemDetails?.seller;
 
 if (seller) {
 result.seller_name = seller.alias || "Private";
 result.address = (seller.zipCode + " " + (seller.city || "")).trim();
 }
 }
} catch (e) {
 console.log("Не удалось вытащить данные продавца из NEXT_DATA");
}

// Запасной вариант для картинки
if (!result.image_url) {
 result.image_url = $('meta[property="og:image"]').attr('content') || "";
}

// 4. Передаем данные обратно в переменные BAS
[[TITLE]] = result.title;
[[PRICE]] = String(result.price); 
[[CURRENCY]] = result.currency;
[[ADDRESS]] = result.address || "Не найдено";
[[IMAGE_URL]] = result.image_url;
[[SELLER_NAME]] = result.seller_name;
