// Входящая переменная из BAS
let html = [[SAVED_PAGE_HTML]]; 
const $ = cheerio.load(html);

// 1. Title
let title = $('meta[property="og:title"]').attr('content') || $('title').text();
if (title) title = title.replace(' | Vinted', '').trim();

// 2. Поиск ЦЕНЫ (Строго по данным из предоставленного файла)
let price = "Не найдено";

// А. Проверка мета-тега (Vinted всегда пишет цену сюда для ботов)
price = $('meta[property="product:price:amount"]').attr('content');

// Б. Если мета-тег пустой, берем из JSON __NEXT_DATA__ (он есть в вашем файле)
if (!price || price === "Не найдено") {
 const jsonText = $('#__NEXT_DATA__').html();
 if (jsonText) {
 try {
 const fullJson = JSON.parse(jsonText);
 // Точный путь в структуре Vinted внутри вашего файла
 const item = fullJson.props.pageProps.item;
 if (item && item.price) {
 price = item.price.amount;
 }
 } catch (e) {}
 }
}

// 3. Другие данные (Город, Продавец, Фото)
let adData = {};
try {
 const fullJson = JSON.parse($('#__NEXT_DATA__').html());
 const item = fullJson.props.pageProps.item;
 adData = {
 address: item.city || "Не найдено",
 seller: item.user ? item.user.login : "Private",
 image: item.photos && item.photos[0] ? item.photos[0].url : ""
 };
} catch (e) {
 adData = {
 address: "Не найдено",
 seller: "Private",
 image: $('meta[property="og:image"]').attr('content')
 };
}

// 4. Передаем данные обратно в переменные BAS
[[TITLE]] = title || "Не найдено";
[[PRICE]] = price ? price.toString() : "Не найдено";
[[ADDRESS]] = adData.address;
[[IMAGE_URL]] = adData.image;
