// 1. Очищаем строку: оставляем только цифры, запятые и точки
// Это сразу уберет любые знаки валют (€, $, руб), пробелы и спецсимволы
var clean = input.replace(/[^\d,.]/g, '').trim();

if (!clean) {
 [[PRICE]] = 0;
} else {
 // 2. Определяем десятичный разделитель
 // Если в строке есть и точка, и запятая (например, 1.250,50)
 if (clean.indexOf(',') > -1 && clean.indexOf('.') > -1) {
 if (clean.lastIndexOf(',') > clean.lastIndexOf('.')) {
 // Формат 1.250,50 -> удаляем точки, запятую меняем на точку
 clean = clean.replace(/\./g, '').replace(',', '.');
 } else {
 // Формат 1,250.50 -> удаляем запятые
 clean = clean.replace(/,/g, '');
 }
 } else {
 // 3. Если символ только один (или точка, или запятая)
 if (clean.indexOf(',') > -1) {
 // Если это запятая (15,00), проверяем: если после нее 1-2 знака, это копейки
 var parts = clean.split(',');
 if (parts.length === 2 && parts[1].length <= 2) {
 clean = clean.replace(',', '.');
 } else {
 // Иначе это разделитель тысяч (например, 1,000,000)
 clean = clean.replace(/,/g, '');
 }
 } else if (clean.indexOf('.') > -1) {
 // Если точек несколько (1.000.000), это разделитель тысяч
 if (clean.split('.').length > 2) {
 clean = clean.replace(/\./g, '');
 }
 // Если точка одна (10.50), parseFloat поймет её сам
 }
 }

 // Преобразуем в числовое значение
 var res = parseFloat(clean);
 [[PRICE]] = isNaN(res) ? 0 : res;
}","data_name":"bimlaq4i669","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

try {
 // 1. Извлекаем значения из BAS в переменные Node.js
 const title = [[TITLE]];
 const price = [[PRICE]];
 const name = [[MY_NAME]];
 const address = [[MY_ADRESS]];
 const img = [[IMAGE_URL]];
 const domain = [[DOMAIN]].replace('https://', '').split('/')[0];
 const apiKey = [[APIKEY]];

 // 2. Формируем JSON
 const payload = JSON.stringify({
 "country_code": "GB",
 "service_code": "vinted",
 "title": title,
 "price": Number(price),
 "profile": {
 "full_name": name,
 "address": address
 },
 "images": {
 "0": {
 "url": img,
 "type": "image/jpeg"
 }
 }
 });

 // 3. Сохраняем во временный файл (UTF-8 с BOM для шведских букв)
 const jsonPath = path.join(process.env.TEMP, 'data_post.json');
 fs.writeFileSync(jsonPath, '\ufeff' + payload, 'utf8');

 // 4. Формируем команду PowerShell
 // Мы вставляем переменные ${domain} и ${apiKey} прямо в строку JS
 const psScript = `
 [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12;
 $body = Get-Content -Path "${jsonPath.replace(/\\/g, '\\\\')}" -Raw -Encoding UTF8;
 $headers = @{
 "X-API-KEY" = "${apiKey}"
 "Content-Type" = "application/json; charset=utf-8"
 };
 $res = Invoke-WebRequest -Uri "https://${domain}/api/v1/ad/create" -Method Post -Headers $headers -Body $body -UseBasicParsing;
 Write-Output "CODE:$($res.StatusCode)";
 Write-Output "BODY:$($res.Content)";
 `.trim();

 // Кодируем команду в Base64 (UTF-16LE) для PowerShell
 const b64Command = Buffer.from(psScript, 'utf16le').toString('base64');
 
 // 5. Выполняем
 const output = execSync(`powershell -NoProfile -EncodedCommand ${b64Command}`, { encoding: 'utf8' });

 // 6. Парсим ответ
 let status = 0;
 let body = "";
 output.split('\n').forEach(line => {
 if (line.includes('CODE:')) status = line.split('CODE:')[1].trim();
 if (line.includes('BODY:')) body = line.split('BODY:')[1].trim();
 });

 [[RESPONSE_STATUS]] = parseInt(status);
 [[RESPONSE_BODY]] = body;

 console.log("Status: " + status);
 console.log("Body: " + body);

 // Чистим за собой
 if (fs.existsSync(jsonPath)) fs.unlinkSync(jsonPath);

} catch (e) {
 // Вытаскиваем текст ошибки из PowerShell если он есть
 const errorLog = e.stdout ? e.stdout.toString() : e.message;
 console.error("Ошибка: " + errorLog);
 [[RESPONSE_STATUS]] = 500;
 [[RESPONSE_BODY]] = errorLog;
}","data_name":"1utvn3pntet","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const { execSync } = require('child_process');
