// 1. Очищаем строку: оставляем только цифры, запятые и точки
// Это сразу уберет любые знаки валют (€, $, руб), пробелы и спецсимволы
var clean = input.replace(/[^\d,.]/g, '').trim();

if (!clean) {
 [[PRICE]] = 0;
} else {
 // 2. Определяем десятичный разделитель
 // Если в строке есть и точка, и запятая (например, 1.250,50)
 if (clean.indexOf(',') > -1 && clean.indexOf('.') > -1) {
 if (clean.lastIndexOf(',') > clean.lastIndexOf('.')) {
 // Формат 1.250,50 -> удаляем точки, запятую меняем на точку
 clean = clean.replace(/\./g, '').replace(',', '.');
 } else {
 // Формат 1,250.50 -> удаляем запятые
 clean = clean.replace(/,/g, '');
 }
 } else {
 // 3. Если символ только один (или точка, или запятая)
 if (clean.indexOf(',') > -1) {
 // Если это запятая (15,00), проверяем: если после нее 1-2 знака, это копейки
 var parts = clean.split(',');
 if (parts.length === 2 && parts[1].length <= 2) {
 clean = clean.replace(',', '.');
 } else {
 // Иначе это разделитель тысяч (например, 1,000,000)
 clean = clean.replace(/,/g, '');
 }
 } else if (clean.indexOf('.') > -1) {
 // Если точек несколько (1.000.000), это разделитель тысяч
 if (clean.split('.').length > 2) {
 clean = clean.replace(/\./g, '');
 }
 // Если точка одна (10.50), parseFloat поймет её сам
 }
 }

 // Преобразуем в числовое значение
 var res = parseFloat(clean);
 [[PRICE]] = isNaN(res) ? 0 : res;
}","data_name":"j66vhb5kq9","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[PARSED_DATA]];
 const searchSubject = [[SUBJECT]].toString().trim().toLowerCase();
 const searchLogin = [[LOGIN]].toString().trim().toLowerCase();
 
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[1]; 
 
 if (!sheetName) throw new Error("Лист с индексом 1 не найден");

 const data = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: "" });
 let found = false;

 for (let i = 1; i < data.length; i++) {
 const row = data[i];
 if (!row || row.length < 5) continue; // Пропуск пустых строк

 const rowItemName = row[1] ? row[1].toString().trim().toLowerCase() : "";
 const rowLogin = row[3] ? row[3].toString().trim().toLowerCase() : "";
 
 // Берем статус как есть, без лишних преобразований вначале
 const rawStatus = row[4];
 const statusValue = parseInt(rawStatus);

 // Фильтр: строго 0 или 1. Если там 2, 2.0 или "2" - это условие НЕ пройдет.
 const statusMatch = (statusValue === 0 || statusValue === 1) && rawStatus !== "";

 const loginMatch = (rowLogin === searchLogin);
 const itemMatch = rowItemName !== "" && (searchSubject.includes(rowItemName) || rowItemName.includes(searchSubject));

 if (loginMatch && itemMatch) {
 // Если логин и имя совпали, но статус не подошел, выведем в лог для дебага
 if (!statusMatch) {
 continue;
 }

 [[LINK]] = row[2];
 found = true;
 console.log(`Найдено! Ряд: ${i + 1}, Статус: ${statusValue}`);
 break; 
 }
 }

 if (found) {
 [[IS_FONDED]] = true;
 } else {
 [[IS_FONDED]] = false;
 }

} catch (e) {
 console.log("Ошибка: " + e.message);
 [[IS_FONDED]] = false;
}","data_name":"qc263nbj0y","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[CONFIG_BAS]]; 
 const targetMarketplace = String([[MARKETPLACE]] || "").trim();
 const targetCurrency = String([[CURRENCY]] || "").trim();
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[4]; // 5-й лист
 const worksheet = workbook.Sheets[sheetName];
 const data = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

 let foundRow = null;

 for (let i = 0; i < data.length; i++) {
 const row = data[i];
 if (!row || row.length === 0) continue;

 // Принудительно в строку для сравнения
 const rowMarketplace = String(row[4] || "").trim();
 const rowCurrency = String(row[3] || "").trim();

 if (rowMarketplace === targetMarketplace) {
 if (targetMarketplace.includes("depop.com")) {
 if (rowCurrency === targetCurrency) {
 foundRow = row;
 break;
 }
 } else {
 foundRow = row;
 break;
 }
 }
 }

 if (foundRow) {
 // ФУНКЦИЯ-ПОМОЩНИК: гарантирует, что BAS получит строку, а не null/undefined
 const clean = (val) => (val !== undefined && val !== null) ? String(val) : "";

 // Прямое присваивание через глобальные переменные BAS
 [[TEAM]] = clean(foundRow[0]);
 [[APIKEY]] = clean(foundRow[1]);
 [[DOMAIN]] = clean(foundRow[2]);
 [[PR_ID_CURRENCY]] = clean(foundRow[3]);
 [[MARKETPLACE]] = clean(foundRow[4]);
 [[TEXT1]] = clean(foundRow[5]);
 [[TEXT2]] = clean(foundRow[6]);
 [[MY_NAME]] = clean(foundRow[7]);
 [[MY_ADRESS]] = clean(foundRow[8]);

 } else {
 console.log("!!! СОВПАДЕНИЙ НЕ НАЙДЕНО. Проверь регистр и пробелы в Excel.");
 }

} catch (e) {
 console.error("!!! ОШИБКА: " + e.message);
}","data_name":"xrt9fbbo0m","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[PARSED_DATA]];
 // Тема из BAS для поиска (базовая)
 const searchSubject = [[SUBJECT]].toString().trim().toLowerCase();
 const searchLogin = [[LOGIN]].toString().trim().toLowerCase();
 
 // 1. Читаем книгу
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[1]; // Лист с индексом 1
 
 if (!sheetName) {
 throw new Error("Лист с индексом 1 не найден в файле");
 }

 // 2. Преобразуем лист в массив массивов
 let data = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: "" });

 let updatedCount = 0;

 // 3. Поиск по всем строкам
 // Начинаем с 1, если есть заголовки. Если данных много, цикл проверит всё.
 for (let i = 1; i < data.length; i++) {
 const row = data[i];

 // Приводим данные из Excel к нижнему регистру для гибкого поиска
 const rowSubject = row[1] ? row[1].toString().trim().toLowerCase() : "";
 const rowLogin = row[3] ? row[3].toString().trim().toLowerCase() : "";

 // Условие: частичное совпадение темы И строгое совпадение логина
 const subjectMatch = rowSubject.includes(searchSubject) || searchSubject.includes(rowSubject);
 const loginMatch = (rowLogin === searchLogin);

 if (subjectMatch && loginMatch) {
 // 4. Меняем статус на 2 во всех найденных строках
 data[i][4] = 2; 
 updatedCount++;
 }
 }

 // 5. Если хотя бы одна запись была изменена, сохраняем файл
 if (updatedCount > 0) {
 workbook.Sheets[sheetName] = XLSX.utils.aoa_to_sheet(data);
 XLSX.writeFile(workbook, filePath);
 
 console.log("Обновление завершено. Изменено строк: " + updatedCount + " для темы: " + [[SUBJECT]]);
 [[IS_UPDATED]] = true;
 } else {
 console.log("Ни одной записи для обновления не найдено.");
 [[IS_UPDATED]] = false;
 }

} catch (e) {
 console.log("Ошибка при массовом обновлении PARSED_DATA: " + e.message);
 [[IS_UPDATED]] = false;
}","data_name":"f53alnbo3m6","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');
const fs = require('fs');

let success = false;
let attempts = 0;

while (!success) {
 try {
 const filePath = [[PARSED_DATA]];
 
 if (!fs.existsSync(filePath)) {
 throw new Error("Файл не найден");
 }

 // 1. Читаем книгу
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[0]; 
 const worksheet = workbook.Sheets[sheetName];

 // 2. Преобразуем в массив массивов
 // header: 1 возвращает данные как массив строк
 const data = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: "" });

 // 3. Подсчет без фильтрации
 // Если строк меньше или равно 1 — значит данных нет (только заголовок или пусто)
 let count = 0;
 if (data.length > 1) {
 count = data.length - 1; // Вычитаем строку заголовка
 }

 // Сохраняем результат в переменную BAS
 [[COUNT_LISTING]] = count;

 console.log("Общее количество объявлений в таблице (без учета заголовка): " + count);
 
 success = true; 

 } catch (e) {
 attempts++;
 
 // Задержка 100 мс (актуально, если файл занят другим процессом)
 var start = new Date().getTime();
 while (new Date().getTime() < start + 100); 
 
 if (attempts > 500) {
 console.log("Критическая ошибка: не удалось обработать файл после 500 попыток. " + e.message);
 [[COUNT_LISTING]] = 0;
 break;
 }
 }
}","data_name":"t0x1wl9jgu","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[PARSED_DATA]];
 // Тема письма, которую мы получили (приводим к нижнему регистру для поиска)
 const searchSubject = [[SUBJECT]].toString().trim().toLowerCase();
 const searchLogin = [[LOGIN]].toString().trim().toLowerCase();
 
 const workbook = XLSX.readFile(filePath);
 const sheetName = workbook.SheetNames[1]; // Лист с индексом 1
 
 if (!sheetName) throw new Error("Лист с индексом 1 не найден");

 const data = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: "" });
 let found = false;

 // Перебор строк (пропускаем заголовки)
 for (let i = 1; i < data.length; i++) {
 const row = data[i];

 // Индекс 1 — Название товара (Item Name)
 // Индекс 3 — Логин (Login)
 // Индекс 4 — Статус
 const rowItemName = row[1] ? row[1].toString().trim().toLowerCase() : "";
 const rowLogin = row[3] ? row[3].toString().trim().toLowerCase() : "";
 const rowStatus = row[4];

 // Сравнение логина
 const loginMatch = (rowLogin === searchLogin);

 // Сравнение товара и темы письма (содержит ли одно другое)
 // Мы проверяем, есть ли название товара внутри темы письма
 const itemMatch = rowItemName !== "" && (searchSubject.includes(rowItemName) || rowItemName.includes(searchSubject));

 // Проверка статуса (0 или 1)
 const statusValue = Number(rowStatus);
 const statusMatch = (statusValue === 0 || statusValue === 1);

 if (loginMatch && itemMatch && statusMatch) {
 // Если всё совпало, берем ссылку из колонки с индексом 2
 [[LINK]] = row[2];
 found = true;
 break; 
 }
 }

 if (found) {
 [[IS_FONDED]] = true;
 console.log("Запись успешно найдена по товару и логину. Товар: " + [[SUBJECT]]);
 } else {
 [[IS_FONDED]] = false;
 console.log("Запись не найдена. Логин: " + searchLogin + " | Тема: " + searchSubject);
 }

} catch (e) {
 console.log("Ошибка при поиске в PARSED_DATA: " + e.message);
 [[IS_FONDED]] = false;
}","data_name":"qn35l86v3p","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

