// Входящая переменная из BAS (содержимое страницы)
// Предположим, ты сохранил код страницы в переменную [[SAVED_HTML]]
let html = [[SAVED_PAGE_HTML]]; 
const $ = cheerio.load(html);

// 1. Title (из мета-тегов или title)
let title = $('title').text().split('|')[0].trim();

// 2. Достаем JSON с данными (там есть цена, картинки и параметры)
let adData = {};
const jsonText = $('#advertising-initial-state').html();

if (jsonText) {
 try {
 const fullJson = JSON.parse(jsonText);
 const targeting = fullJson.config.adServer.gam.targeting;
 
 // Преобразуем массив таргетинга в удобный объект
 targeting.forEach(item => {
 adData[item.key] = item.value[0];
 });
 } catch (e) {
 console.error("Ошибка парсинга JSON:", e);
 }
}

// 3. Собираем финальные данные
let result = {
 title: title,
 price: adData['price'] || "Не найдено",
 address: adData['zipcode'] || "Не найдено", // В коде есть только индекс
 image_url: $('meta[property="og:image"]').attr('content') || adData['images'],
 seller_name: adData['owner_type'] === 'private' ? 'Private' : 'Private' 
};

// 4. Передаем данные обратно в переменные BAS
[[TITLE]] = result.title;
[[PRICE]] = result.price;
[[ADDRESS]] = result.address;
[[IMAGE_URL]] = result.image_url;
[[SELLER_NAME]] = result.seller_name;","data_name":"wzju1uf8vni","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"var input = [[SAVED_TEXT]];

// 1. Очищаем строку: оставляем только цифры, запятые и точки
// Это сразу уберет любые знаки валют (€, $, руб), пробелы и спецсимволы
var clean = input.replace(/[^\d,.]/g, '').trim();

if (!clean) {
 [[PRICE]] = 0;
} else {
 // 2. Определяем десятичный разделитель
 // Если в строке есть и точка, и запятая (например, 1.250,50)
 if (clean.indexOf(',') > -1 && clean.indexOf('.') > -1) {
 if (clean.lastIndexOf(',') > clean.lastIndexOf('.')) {
 // Формат 1.250,50 -> удаляем точки, запятую меняем на точку
 clean = clean.replace(/\./g, '').replace(',', '.');
 } else {
 // Формат 1,250.50 -> удаляем запятые
 clean = clean.replace(/,/g, '');
 }
 } else {
 // 3. Если символ только один (или точка, или запятая)
 if (clean.indexOf(',') > -1) {
 // Если это запятая (15,00), проверяем: если после нее 1-2 знака, это копейки
 var parts = clean.split(',');
 if (parts.length === 2 && parts[1].length <= 2) {
 clean = clean.replace(',', '.');
 } else {
 // Иначе это разделитель тысяч (например, 1,000,000)
 clean = clean.replace(/,/g, '');
 }
 } else if (clean.indexOf('.') > -1) {
 // Если точек несколько (1.000.000), это разделитель тысяч
 if (clean.split('.').length > 2) {
 clean = clean.replace(/\./g, '');
 }
 // Если точка одна (10.50), parseFloat поймет её сам
 }
 }

 // Преобразуем в числовое значение
 var res = parseFloat(clean);
 [[PRICE]] = isNaN(res) ? 0 : res;
}","data_name":"e1hykprmqxd","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const cheerio = require('cheerio');

