try {
 // 1. Читаем файл
 const workbook = XLSX.readFile([[CONFIG_BAS]]);
 const sheetName = workbook.SheetNames[0];
 const worksheet = workbook.Sheets[sheetName];

 // 2. Обязательно добавляем { header: 1 }, чтобы работать с индексами 0, 1, 2...
 const data = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: "" });

 // 3. Получаем индекс
 // Если первая строка в таблице — это заголовки, прибавьте +1: parseInt([[THREAD_INDEX]]) + 1
 const index = parseInt([[THREAD_INDEX]]);
 const row = data[index];

 if (row) {
 // Присваиваем значения переменным BAS напрямую
 // Убедитесь, что эти переменные созданы в интерфейсе BAS
 [[ID]] = row[0];
 [[LOGIN]] = row[1];
 [[PASS]] = row[2];
 [[RECOVERY_MAIL]] = row[3];
 [[TWO_FA_KEY]] = row[4];
 [[PROXY]] = row[5];
 [[BANED]] = row[6];
 [[DAILY_LIMIT]] = row[7];
 [[CURRENT_LIMIT]] = row[8];
 [[STATUS_LIMIT]] = row[9];
 
 } else {
 console.log("Ошибка: Строка с индексом " + index + " не найдена!");
 }
} catch (e) {
 console.log("Произошла ошибка при чтении Excel: " + e.message);
}","data_name":"slgz4ol03s","data_type":0,"language_name":"Node","language_version":"22.11.0"},{"data":"const XLSX = require('xlsx');

try {
 const filePath = [[CONFIG_BAS]];
 const threadIndex = parseInt([[THREAD_INDEX]]);
 
 // По умолчанию 0 (ошибка)
 [[STATUS_CHANGE]] = 0;
 [[IS_SUCCESS]] = false;

 const workbook = XLSX.readFile(filePath);
 
 const sheet0Name = workbook.SheetNames[0]; // Лист с воркерами
 const sheet2Name = workbook.SheetNames[2]; // Лист с резервом
 const sheet3Name = workbook.SheetNames[3]; // Лист с архивом

 let sheet0Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet0Name], { header: 1, defval: "" });
 let sheet2Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet2Name], { header: 1, defval: "" });
 let sheet3Data = XLSX.utils.sheet_to_json(workbook.Sheets[sheet3Name], { header: 1, defval: "" });

 // Проверяем, существует ли строка воркера в Листе 0
 if (sheet0Data[threadIndex]) {
 
 // --- ШАГ 1: Архивируем старые данные из Листа 0 в Лист 3 ---
 const rowToArchive = [...sheet0Data[threadIndex]];
 const timestamp = new Date().toLocaleString();
 rowToArchive[18] = timestamp; // Записываем время архивации в колонку S (индекс 18)
 sheet3Data.push(rowToArchive);
 console.log(`Поток ${threadIndex}: Старые данные отправлены в архив.`);

 // --- ШАГ 2: Берем САМУЮ ПЕРВУЮ строку из Резерва (Лист 2) ---
 // Индекс 0 — это заголовки, поэтому первая строка данных — это индекс 1
 if (sheet2Data.length > 1) {
 // .splice(1, 1) удаляет одну строку по индексу 1 и возвращает её массивом
 const replacementRow = sheet2Data.splice(1, 1)[0];
 
 // Заменяем строку воркера на новую из резерва
 sheet0Data[threadIndex] = replacementRow;
 
 [[STATUS_CHANGE]] = 1; // Успешная замена
 console.log(`Поток ${threadIndex}: Взята новая строка из резерва (индекс 1).`);
 } else {
 // Если в резерве только заголовки (длина 1) или пусто
 console.log(`Поток ${threadIndex}: РЕЗЕРВ ПУСТ! Очищаю рабочую строку.`);
 sheet0Data[threadIndex] = []; // Очищаем строку, так как заменять нечем
 
 [[STATUS_CHANGE]] = 2; // Резерв закончился
 }

 // --- ШАГ 3: Сохранение всех листов обратно в файл ---
 workbook.Sheets[sheet0Name] = XLSX.utils.aoa_to_sheet(sheet0Data);
 workbook.Sheets[sheet2Name] = XLSX.utils.aoa_to_sheet(sheet2Data);
 workbook.Sheets[sheet3Name] = XLSX.utils.aoa_to_sheet(sheet3Data);

 XLSX.writeFile(workbook, filePath);
 [[IS_SUCCESS]] = true;

 } else {
 console.log("Ошибка: Индекс потока " + threadIndex + " не найден в Листе 0.");
 [[IS_SUCCESS]] = false;
 }

} catch (e) {
 console.error("Критическая ошибка при ротации аккаунтов: " + e.message);
 [[STATUS_CHANGE]] = 0;
 [[IS_SUCCESS]] = false;
}","data_name":"l4dlsgw4qwi","data_type":0,"language_name":"Node","language_version":"22.11.0"}]
